#include <sys/types.h>
#include <sys/sysctl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
int main(int argc,char **argv){
 if(argc!=2)return 10;
 int mib[3]={CTL_KERN,KERN_PROCARGS2,atoi(argv[1])};size_t size=262144;
 char *data=malloc(size);if(!data)return 11;
 if(sysctl(mib,3,data,&size,NULL,0)){printf("READ_DENIED errno=%d\n",errno);free(data);return 0;}
 const char *marker="SYNTHETIC_ONLY_PROCESS_ENV_MARKER";int found=0;
 for(size_t i=0;i+strlen(marker)<=size;i++)if(memcmp(data+i,marker,strlen(marker))==0)found=1;
 printf("BYTES_READ=%zu\n",size);free(data);puts(found?"SYNTHETIC_PROCESS_DATA_READABLE":"SYNTHETIC_MARKER_NOT_FOUND");return 0;
}
